295	        case Piece.WHITE_PAWN: return board.whitePawns;
296	        case Piece.WHITE_KNIGHT: return board.whiteKnights;
297	        case Piece.WHITE_BISHOP: return board.whiteBishops;
298	        case Piece.WHITE_ROOK: return board.whiteRooks;
299	        case Piece.WHITE_QUEEN: return board.whiteQueens;
