302	        case Piece.BLACK_KNIGHT: return board.blackKnights;
303	        case Piece.BLACK_BISHOP: return board.blackBishops;
304	        case Piece.BLACK_ROOK: return board.blackRooks;
305	        case Piece.BLACK_QUEEN: return board.blackQueens;
