311	/**
312	 * Copy a board (efficient struct copy)
313	 *
314	 * @param source - Source board
315	 * @returns New board with same state
316	 */
317	export function copyBoard(source: InternalBoard): InternalBoard {
318	    return {
319	        // Copy mailbox
320	        mailbox: new Int8Array(source.mailbox),
321	
322	        // Copy bitboards (primitives, so direct copy)
323	        whitePawns: source.whitePawns,
324	        whiteKnights: source.whiteKnights,
325	        whiteBishops: source.whiteBishops,
326	        whiteRooks: source.whiteRooks,
327	        whiteQueens: source.whiteQueens,
328	        whiteKing: source.whiteKing,
329	        blackPawns: source.blackPawns,
330	        blackKnights: source.blackKnights,
331	        blackBishops: source.blackBishops,
332	        blackRooks: source.blackRooks,
333	        blackQueens: source.blackQueens,
334	        blackKing: source.blackKing,
335	        whitePieces: source.whitePieces,
336	        blackPieces: source.blackPieces,
337	        allPieces: source.allPieces,
338	
339	        // Copy game state
340	        turn: source.turn,
341	        castlingRights: { ...source.castlingRights },
342	        enPassantSquare: source.enPassantSquare,
343	        halfMoveClock: source.halfMoveClock,
344	        fullMoveNumber: source.fullMoveNumber,
345	        zobristHash: source.zobristHash,
346	        isCheck: source.isCheck,
347	        isCheckmate: source.isCheckmate,
348	        isStalemate: source.isStalemate,
349	    };
350	}
351	
352	/**
353	 * Check if a piece belongs to a specific color
354	 *
355	 * @param piece - Piece to check
356	 * @param color - Color to check
357	 * @returns true if piece is of the given color
358	 */
359	export function isPieceColor(piece: Piece, color: InternalColor): boolean {
360	    if (piece === Piece.EMPTY) {
361	        return false;
362	    }
363	
364	    if (color === InternalColor.WHITE) {
365	        return piece >= Piece.WHITE_PAWN && piece <= Piece.WHITE_KING;
366	    } else {
367	        return piece >= Piece.BLACK_PAWN && piece <= Piece.BLACK_KING;
368	    }
369	}
370	
371	/**
372	 * Get the color of a piece
373	 *
374	 * @param piece - Piece to check
375	 * @returns Color of the piece, or null if empty
376	 */
377	export function getPieceColor(piece: Piece): InternalColor | null {
378	    if (piece === Piece.EMPTY) {
379	        return null;
380	    }
381	    return piece >= Piece.WHITE_PAWN && piece <= Piece.WHITE_KING
382	        ? InternalColor.WHITE
383	        : InternalColor.BLACK;
384	}
385	
386	/**
387	 * Get the opposite color
388	 *
389	 * @param color - Color
390	 * @returns Opposite color
391	 */
392	export function oppositeColor(color: InternalColor): InternalColor {
393	    return color === InternalColor.WHITE ? InternalColor.BLACK : InternalColor.WHITE;
394	}
395	
396	/**
397	 * Check if a square is empty
398	 *
399	 * @param board - Board to check
400	 * @param index - Square index
401	 * @returns true if square is empty
402	 */
403	export function isSquareEmpty(board: InternalBoard, index: SquareIndex): boolean {
404	    return board.mailbox[index] === Piece.EMPTY;
405	}
406	
407	/**
408	 * Check if a square is occupied by an enemy piece
409	 *
410	 * @param board - Board to check
411	 * @param index - Square index
412	 * @param color - Our color
413	 * @returns true if square has enemy piece
414	 */
415	export function isSquareEnemy(board: InternalBoard, index: SquareIndex, color: InternalColor): boolean {
416	    const piece = board.mailbox[index];
417	    if (piece === Piece.EMPTY) {
418	        return false;
419	    }
420	    const pieceColor = getPieceColor(piece);
421	    return pieceColor !== null && pieceColor !== color;
422	}
423	
424	/**
425	 * Check if a square is occupied by a friendly piece
426	 *
427	 * @param board - Board to check
428	 * @param index - Square index
429	 * @param color - Our color
430	 * @returns true if square has friendly piece
431	 */
432	export function isSquareFriendly(board: InternalBoard, index: SquareIndex, color: InternalColor): boolean {
433	    const piece = board.mailbox[index];
434	    if (piece === Piece.EMPTY) {
435	        return false;
436	    }
437	    return isPieceColor(piece, color);
438	}
