64	        if (move.flags & MoveFlag.CASTLING) {
65	            return true;
66	        }
67	
68	        // Make the move on a temporary board copy to check if it's legal
69	        const testBoard = copyBoard(board);
70	        const originalTurn = testBoard.turn;
71	        makeMove(testBoard, move);
72	
73	        // After making the move, check if OUR king (the one that just moved) is in check
74	        // makeMove switches the turn, so we need to check the OPPOSITE color
75	        const kingBitboardAfter = originalTurn === InternalColor.WHITE ? testBoard.whiteKing : testBoard.blackKing;
