393	/**
394	 * Generate knight moves
395	 */
396	function generateKnightMoves(
397	    board: InternalBoard,
398	    moves: InternalMove[],
399	    color: InternalColor,
400	    friendlyPieces: Bitboard
401	): void {
402	    const knights = color === InternalColor.WHITE ? board.whiteKnights : board.blackKnights;
403	    const knightPiece = color === InternalColor.WHITE ? Piece.WHITE_KNIGHT : Piece.BLACK_KNIGHT;
404	
405	    let knightsBB = knights;
406	    while (knightsBB !== 0n) {
407	        const from = getLowestSetBit(knightsBB);
408	        const attacks = getKnightAttacks(from) & ~friendlyPieces;
409	
410	        let attacksBB = attacks;
411	        while (attacksBB !== 0n) {
412	            const to = getLowestSetBit(attacksBB) as SquareIndex;
413	            attacksBB &= attacksBB - 1n;
414	            const capturedPiece = getPiece(board, to);
415	            const flags = capturedPiece !== Piece.EMPTY ? MoveFlag.CAPTURE : MoveFlag.NONE;
416	            moves.push(createMove(from, to, knightPiece, capturedPiece, flags));
417	        }
418	
419	        knightsBB &= knightsBB - 1n; // Clear lowest bit
420	    }
