431	): void {
432	    const bishops = color === InternalColor.WHITE ? board.whiteBishops : board.blackBishops;
433	    const bishopPiece = color === InternalColor.WHITE ? Piece.WHITE_BISHOP : Piece.BLACK_BISHOP;
434	
435	    let bishopsBB = bishops;
436	    while (bishopsBB !== 0n) {
437	        const from = getLowestSetBit(bishopsBB);
438	        const attacks = getBishopAttacks(from, board.allPieces) & ~friendlyPieces;
439	
440	        let attacksBB = attacks;
441	        while (attacksBB !== 0n) {
442	            const to = getLowestSetBit(attacksBB) as SquareIndex;
443	            attacksBB &= attacksBB - 1n;
444	            const capturedPiece = getPiece(board, to);
445	            const flags = capturedPiece !== Piece.EMPTY ? MoveFlag.CAPTURE : MoveFlag.NONE;
446	            moves.push(createMove(from, to, bishopPiece, capturedPiece, flags));
447	        }
448	
449	        bishopsBB &= bishopsBB - 1n;
450	    }
451	}
452	
