512	
513	/**
514	 * Generate king moves (excluding castling)
515	 */
516	function generateKingMoves(
517	    board: InternalBoard,
518	    moves: InternalMove[],
519	    color: InternalColor,
520	    friendlyPieces: Bitboard
521	): void {
522	    const king = color === InternalColor.WHITE ? board.whiteKing : board.blackKing;
523	    const kingPiece = color === InternalColor.WHITE ? Piece.WHITE_KING : Piece.BLACK_KING;
524	
525	    if (king === 0n) return;
526	
527	    const from = getLowestSetBit(king);
528	    const attacks = getKingAttacks(from) & ~friendlyPieces;
529	
530	    let attacksBB = attacks;
531	    while (attacksBB !== 0n) {
532	        const to = getLowestSetBit(attacksBB) as SquareIndex;
533	        attacksBB &= attacksBB - 1n;
534	        const capturedPiece = getPiece(board, to);
535	        const flags = capturedPiece !== Piece.EMPTY ? MoveFlag.CAPTURE : MoveFlag.NONE;
536	        moves.push(createMove(from, to, kingPiece, capturedPiece, flags));
537	    }
538	}
539	
540	/**
541	 * Generate castling moves
542	 */
543	function generateCastlingMoves(
544	    board: InternalBoard,
545	    moves: InternalMove[],
546	    color: InternalColor
547	): void {
548	    const opponentColor = color === InternalColor.WHITE ? InternalColor.BLACK : InternalColor.WHITE;
549	
550	    if (color === InternalColor.WHITE) {
551	        // White short castling (O-O)
552	        if (
553	            board.castlingRights.whiteShort &&
554	            getPiece(board, CASTLING.WHITE_SHORT.kingFrom as SquareIndex) === Piece.WHITE_KING &&
555	            getPiece(board, CASTLING.WHITE_SHORT.rookFrom as SquareIndex) === Piece.WHITE_ROOK &&
556	            isSquareEmpty(board, 5 as SquareIndex) && // F1
557	            isSquareEmpty(board, 6 as SquareIndex) && // G1
558	            !isSquareAttacked(board, 4 as SquareIndex, opponentColor) && // E1 not in check
559	            !isSquareAttacked(board, 5 as SquareIndex, opponentColor) && // F1 not attacked
560	            !isSquareAttacked(board, 6 as SquareIndex, opponentColor)    // G1 not attacked
561	        ) {
562	            moves.push(createMove(
563	                CASTLING.WHITE_SHORT.kingFrom as SquareIndex,
564	                CASTLING.WHITE_SHORT.kingTo as SquareIndex,
565	                Piece.WHITE_KING,
566	                Piece.EMPTY,
567	                MoveFlag.CASTLING
568	            ));
569	        }
570	
571	        // White long castling (O-O-O)
572	        if (
573	            board.castlingRights.whiteLong &&
574	            getPiece(board, CASTLING.WHITE_LONG.kingFrom as SquareIndex) === Piece.WHITE_KING &&
575	            getPiece(board, CASTLING.WHITE_LONG.rookFrom as SquareIndex) === Piece.WHITE_ROOK &&
576	            isSquareEmpty(board, 1 as SquareIndex) && // B1
577	            isSquareEmpty(board, 2 as SquareIndex) && // C1
578	            isSquareEmpty(board, 3 as SquareIndex) && // D1
579	            !isSquareAttacked(board, 4 as SquareIndex, opponentColor) && // E1 not in check
580	            !isSquareAttacked(board, 3 as SquareIndex, opponentColor) && // D1 not attacked
581	            !isSquareAttacked(board, 2 as SquareIndex, opponentColor)    // C1 not attacked
582	        ) {
583	            moves.push(createMove(
584	                CASTLING.WHITE_LONG.kingFrom as SquareIndex,
585	                CASTLING.WHITE_LONG.kingTo as SquareIndex,
586	                Piece.WHITE_KING,
587	                Piece.EMPTY,
588	                MoveFlag.CASTLING
589	            ));
590	        }
591	    } else {
592	        // Black short castling (O-O)
593	        if (
594	            board.castlingRights.blackShort &&
595	            getPiece(board, CASTLING.BLACK_SHORT.kingFrom as SquareIndex) === Piece.BLACK_KING &&
596	            getPiece(board, CASTLING.BLACK_SHORT.rookFrom as SquareIndex) === Piece.BLACK_ROOK &&
597	            isSquareEmpty(board, 61 as SquareIndex) && // F8
598	            isSquareEmpty(board, 62 as SquareIndex) && // G8
599	            !isSquareAttacked(board, 60 as SquareIndex, opponentColor) && // E8 not in check
600	            !isSquareAttacked(board, 61 as SquareIndex, opponentColor) && // F8 not attacked
601	            !isSquareAttacked(board, 62 as SquareIndex, opponentColor)    // G8 not attacked
602	        ) {
603	            moves.push(createMove(
604	                CASTLING.BLACK_SHORT.kingFrom as SquareIndex,
605	                CASTLING.BLACK_SHORT.kingTo as SquareIndex,
606	                Piece.BLACK_KING,
607	                Piece.EMPTY,
608	                MoveFlag.CASTLING
609	            ));
610	        }
611	
612	        // Black long castling (O-O-O)
613	        if (
614	            board.castlingRights.blackLong &&
615	            getPiece(board, CASTLING.BLACK_LONG.kingFrom as SquareIndex) === Piece.BLACK_KING &&
616	            getPiece(board, CASTLING.BLACK_LONG.rookFrom as SquareIndex) === Piece.BLACK_ROOK &&
617	            isSquareEmpty(board, 57 as SquareIndex) && // B8
618	            isSquareEmpty(board, 58 as SquareIndex) && // C8
619	            isSquareEmpty(board, 59 as SquareIndex) && // D8
620	            !isSquareAttacked(board, 60 as SquareIndex, opponentColor) && // E8 not in check
621	            !isSquareAttacked(board, 59 as SquareIndex, opponentColor) && // D8 not attacked
622	            !isSquareAttacked(board, 58 as SquareIndex, opponentColor)    // C8 not attacked
623	        ) {
624	            moves.push(createMove(
625	                CASTLING.BLACK_LONG.kingFrom as SquareIndex,
626	                CASTLING.BLACK_LONG.kingTo as SquareIndex,
627	                Piece.BLACK_KING,
628	                Piece.EMPTY,
629	                MoveFlag.CASTLING
630	            ));
631	        }
632	    }
633	}
634	
635	/**
636	 * Helper to create a move object
637	 */
638	function createMove(
639	    from: SquareIndex,
640	    to: SquareIndex,
641	    piece: Piece,
642	    capturedPiece: Piece,
643	    flags: MoveFlag,
644	    promotionPiece?: Piece
645	): InternalMove {
646	    return {
647	        from,
648	        to,
649	        piece,
650	        capturedPiece,
651	        flags,
652	        promotionPiece,
653	    };
654	}
655	
656	/**
657	 * Get all legal moves for a specific piece
658	 *
659	 * @param board - Board state
660	 * @param square - Square of the piece
661	 * @returns Array of legal moves for that piece
662	 */
663	export function getMovesForPiece(board: InternalBoard, square: SquareIndex): InternalMove[] {
664	    const allMoves = generateLegalMoves(board);
665	    return allMoves.filter(move => move.from === square);
666	}
667	
668	/**
669	 * Check if a move is legal
670	 *
671	 * @param board - Board state
672	 * @param from - From square
673	 * @param to - To square
674	 * @returns true if move is legal
675	 */
676	export function isMoveLegal(board: InternalBoard, from: SquareIndex, to: SquareIndex): boolean {
677	    const legalMoves = generateLegalMoves(board);
678	    return legalMoves.some(move => move.from === from && move.to === to);
679	}
680	
681	/**
682	 * Apply a move to the board with full state updates (mutates the board)
683	 * Updates turn, castling rights, en passant, move counters, and game status
684	 *
685	 * @param board - Board state to modify
686	 * @param move - Move to apply
687	 * @returns The applied move
688	 */
689	export function applyMoveComplete(board: InternalBoard, move: InternalMove): InternalMove {
690	    const { from, to, piece, capturedPiece, flags, promotionPiece } = move;
691	
692	    // Snapshot state needed for incremental hash updates
693	    const oldEnPassant = board.enPassantSquare;
694	    const oldCastling = { ...board.castlingRights };
695	
696	    // Reset en passant square (will be set if this is a double pawn push)
697	    board.enPassantSquare = null;
698	
699	    // Handle captures (+hash)
700	    if (capturedPiece !== Piece.EMPTY) {
701	        // Remove captured piece from board and hash
702	        removePiece(board, to);
703	        board.zobristHash = updateHashCapture(board.zobristHash, capturedPiece, to);
704	        board.halfMoveClock = 0;
705	    } else {
706	        board.halfMoveClock++;
707	    }
708	
709	    // Handle en passant capture (+hash)
710	    if (flags & MoveFlag.EN_PASSANT) {
711	        const captureSquare = board.turn === InternalColor.WHITE ? to - 8 : to + 8;
712	        const capturedPawn = board.turn === InternalColor.WHITE ? Piece.BLACK_PAWN : Piece.WHITE_PAWN;
713	        removePiece(board, captureSquare as SquareIndex);
714	        board.zobristHash = updateHashCapture(board.zobristHash, capturedPawn, captureSquare as SquareIndex);
715	        board.halfMoveClock = 0;
716	    }
717	
718	    // Handle castling rook move (+hash)
719	    if (flags & MoveFlag.CASTLING) {
720	        if (to === CASTLING.WHITE_SHORT.kingTo) {
721	            removePiece(board, CASTLING.WHITE_SHORT.rookFrom as SquareIndex);
722	            setPiece(board, CASTLING.WHITE_SHORT.rookTo as SquareIndex, Piece.WHITE_ROOK);
723	            board.zobristHash = updateHashMove(
724	                board.zobristHash,
725	                Piece.WHITE_ROOK,
726	                CASTLING.WHITE_SHORT.rookFrom as SquareIndex,
727	                CASTLING.WHITE_SHORT.rookTo as SquareIndex
728	            );
729	        } else if (to === CASTLING.WHITE_LONG.kingTo) {
730	            removePiece(board, CASTLING.WHITE_LONG.rookFrom as SquareIndex);
731	            setPiece(board, CASTLING.WHITE_LONG.rookTo as SquareIndex, Piece.WHITE_ROOK);
732	            board.zobristHash = updateHashMove(
733	                board.zobristHash,
734	                Piece.WHITE_ROOK,
735	                CASTLING.WHITE_LONG.rookFrom as SquareIndex,
736	                CASTLING.WHITE_LONG.rookTo as SquareIndex
737	            );
738	        } else if (to === CASTLING.BLACK_SHORT.kingTo) {
739	            removePiece(board, CASTLING.BLACK_SHORT.rookFrom as SquareIndex);
740	            setPiece(board, CASTLING.BLACK_SHORT.rookTo as SquareIndex, Piece.BLACK_ROOK);
741	            board.zobristHash = updateHashMove(
742	                board.zobristHash,
743	                Piece.BLACK_ROOK,
744	                CASTLING.BLACK_SHORT.rookFrom as SquareIndex,
745	                CASTLING.BLACK_SHORT.rookTo as SquareIndex
746	            );
747	        } else if (to === CASTLING.BLACK_LONG.kingTo) {
748	            removePiece(board, CASTLING.BLACK_LONG.rookFrom as SquareIndex);
749	            setPiece(board, CASTLING.BLACK_LONG.rookTo as SquareIndex, Piece.BLACK_ROOK);
750	            board.zobristHash = updateHashMove(
751	                board.zobristHash,
752	                Piece.BLACK_ROOK,
753	                CASTLING.BLACK_LONG.rookFrom as SquareIndex,
754	                CASTLING.BLACK_LONG.rookTo as SquareIndex
755	            );
756	        }
757	    }
758	
759	    // Move the piece (+hash)
760	    removePiece(board, from);
761	    board.zobristHash = updateHashMove(board.zobristHash, piece, from, to);
762	
763	    // Handle promotion (piece identity at destination changes)
764	    if (flags & MoveFlag.PROMOTION && promotionPiece) {
765	        // updateHashMove added the pawn at `to`, swap it with promotion piece.
766	        board.zobristHash = removePieceFromHash(board.zobristHash, piece, to);
767	        board.zobristHash = addPieceToHash(board.zobristHash, promotionPiece, to);
768	        setPiece(board, to, promotionPiece);
769	    } else {
770	        setPiece(board, to, piece);
771	    }
772	
773	    // Reset half-move clock on pawn moves
774	    if (piece === Piece.WHITE_PAWN || piece === Piece.BLACK_PAWN) {
775	        board.halfMoveClock = 0;
776	    }
777	
778	    // Handle double pawn push (set en passant square)
779	    if (flags & MoveFlag.PAWN_DOUBLE_PUSH) {
780	        const enPassantSquare = board.turn === InternalColor.WHITE ? from + 8 : from - 8;
781	        board.enPassantSquare = enPassantSquare as SquareIndex;
782	    }
783	
784	    // Update castling rights
785	    updateCastlingRights(board, from, to, piece);
786	
787	    // Update hash for castling/en-passant state
788	    board.zobristHash = updateHashEnPassant(board.zobristHash, oldEnPassant, board.enPassantSquare);
789	    board.zobristHash = updateHashCastling(
790	        board.zobristHash,
791	        oldCastling.whiteShort,
792	        board.castlingRights.whiteShort,
793	        oldCastling.whiteLong,
794	        board.castlingRights.whiteLong,
795	        oldCastling.blackShort,
796	        board.castlingRights.blackShort,
797	        oldCastling.blackLong,
798	        board.castlingRights.blackLong
799	    );
800	
801	    // Switch turn (+hash)
802	    board.turn = board.turn === InternalColor.WHITE ? InternalColor.BLACK : InternalColor.WHITE;
803	    board.zobristHash = toggleSide(board.zobristHash);
804	
805	    // Increment full move number after black's move
806	    if (board.turn === InternalColor.WHITE) {
807	        board.fullMoveNumber++;
808	    }
809	
810	    // Update game status (check, checkmate, stalemate)
811	    updateGameStatus(board);
812	
813	    return move;
814	}
815	
816	/**
817	 * Update castling rights after a move
818	 *
819	 * @param board - Board state
820	 * @param from - From square
821	 * @param to - To square
822	 * @param piece - Piece that moved
823	 */
824	function updateCastlingRights(
825	    board: InternalBoard,
826	    from: SquareIndex,
827	    to: SquareIndex,
828	    piece: Piece
829	): void {
830	    // If king moves, lose all castling rights for that color
831	    if (piece === Piece.WHITE_KING) {
832	        board.castlingRights.whiteShort = false;
833	        board.castlingRights.whiteLong = false;
834	    } else if (piece === Piece.BLACK_KING) {
835	        board.castlingRights.blackShort = false;
836	        board.castlingRights.blackLong = false;
837	    }
838	
839	    // If rook moves from starting square, lose castling right for that side
840	    if (piece === Piece.WHITE_ROOK) {
841	        if (from === CASTLING.WHITE_SHORT.rookFrom) {
842	            board.castlingRights.whiteShort = false;
843	        } else if (from === CASTLING.WHITE_LONG.rookFrom) {
844	            board.castlingRights.whiteLong = false;
845	        }
846	    } else if (piece === Piece.BLACK_ROOK) {
847	        if (from === CASTLING.BLACK_SHORT.rookFrom) {
848	            board.castlingRights.blackShort = false;
849	        } else if (from === CASTLING.BLACK_LONG.rookFrom) {
850	            board.castlingRights.blackLong = false;
851	        }
852	    }
853	
854	    // If rook is captured, lose castling right for that side
855	    if (to === CASTLING.WHITE_SHORT.rookFrom) {
856	        board.castlingRights.whiteShort = false;
857	    } else if (to === CASTLING.WHITE_LONG.rookFrom) {
858	        board.castlingRights.whiteLong = false;
859	    } else if (to === CASTLING.BLACK_SHORT.rookFrom) {
860	        board.castlingRights.blackShort = false;
861	    } else if (to === CASTLING.BLACK_LONG.rookFrom) {
862	        board.castlingRights.blackLong = false;
863	    }
864	}
865	
866	/**
867	 * Update game status (check, checkmate, stalemate)
868	 *
869	 * @param board - Board state
870	 */
871	function updateGameStatus(board: InternalBoard): void {
872	    const currentColor = board.turn;
873	    const kingBitboard = currentColor === InternalColor.WHITE ? board.whiteKing : board.blackKing;
874	
875	    if (kingBitboard === 0n) {
876	        board.isCheck = false;
877	        board.isCheckmate = false;
878	        board.isStalemate = false;
879	        return;
880	    }
881	
882	    const kingSquare = getLowestSetBit(kingBitboard) as SquareIndex;
883	    // Check if the current player's king is attacked by the OPPONENT
884	    const opponentColor = currentColor === InternalColor.WHITE ? InternalColor.BLACK : InternalColor.WHITE;
885	    const inCheck = isSquareAttacked(board, kingSquare, opponentColor);
886	
887	    // Fast status update — only sets isCheck.
888	    // IMPORTANT: isCheckmate and isStalemate are NOT set here to avoid recursive
889	    // generateLegalMoves() calls (applyMoveComplete -> updateGameStatus -> generateLegalMoves).
890	    // The search detects mate/stalemate via moves.length === 0.
891	    // The public API (Game class) patches these flags via updateConfigStatusFromBoard().
892	    board.isCheck = inCheck;
893	    board.isCheckmate = false;
894	    board.isStalemate = false;
895	}
