28	/**
29	 * Check if a square is attacked by a specific color
30	 *
31	 * @param board - Board to check
32	 * @param square - Square index to check
33	 * @param attackerColor - Color of attacking pieces
34	 * @returns true if square is attacked by attackerColor
35	 */
36	export function isSquareAttacked(
37	    board: InternalBoard,
38	    square: SquareIndex,
39	    attackerColor: InternalColor
40	): boolean {
41	    const attackers = attackerColor === InternalColor.WHITE ? board.whitePieces : board.blackPieces;
42	
43	    // Check pawn attacks
44	    // IMPORTANT: `getWhitePawnAttacks(square)` returns the squares a *white pawn on `square`*
45	    // would attack (north-east/north-west). For attack detection we need the inverse mapping:
46	    // which pawn squares could attack `square`.
47	    // That means:
48	    //  - to see if `square` is attacked by WHITE pawns, look for WHITE pawns on the squares
49	    //    that a BLACK pawn from `square` would attack (south-east/south-west), i.e. potential
50	    //    white pawn origins.
51	    //  - to see if `square` is attacked by BLACK pawns, look for BLACK pawns on the squares
52	    //    that a WHITE pawn from `square` would attack (north-east/north-west), i.e. potential
53	    //    black pawn origins.
54	    const pawnAttackOrigins = attackerColor === InternalColor.WHITE
55	        ? getBlackPawnAttacks(square)
56	        : getWhitePawnAttacks(square);
57	
58	    const pawns = attackerColor === InternalColor.WHITE ? board.whitePawns : board.blackPawns;
59	    if ((pawnAttackOrigins & pawns) !== 0n) {
60	        return true;
61	    }
62	
63	    // Check knight attacks
64	    const knightAttacks = getKnightAttacks(square);
65	    const knights = attackerColor === InternalColor.WHITE ? board.whiteKnights : board.blackKnights;
66	    if ((knightAttacks & knights) !== 0n) {
67	        return true;
68	    }
69	
70	    // Check bishop and queen diagonal attacks
71	    const bishopAttacks = getBishopAttacks(square, board.allPieces);
72	    const bishops = attackerColor === InternalColor.WHITE ? board.whiteBishops : board.blackBishops;
73	    const queens = attackerColor === InternalColor.WHITE ? board.whiteQueens : board.blackQueens;
74	    if ((bishopAttacks & (bishops | queens)) !== 0n) {
75	        return true;
76	    }
77	
78	    // Check rook and queen straight attacks
79	    const rookAttacks = getRookAttacks(square, board.allPieces);
80	    const rooks = attackerColor === InternalColor.WHITE ? board.whiteRooks : board.blackRooks;
81	    if ((rookAttacks & (rooks | queens)) !== 0n) {
82	        return true;
83	    }
84	
85	    // Check king attacks
86	    const kingAttacks = getKingAttacks(square);
87	    const king = attackerColor === InternalColor.WHITE ? board.whiteKing : board.blackKing;
88	    if ((kingAttacks & king) !== 0n) {
89	        return true;
90	    }
91	
92	    return false;
93	}
94	
95	/**
96	 * Check if the current player's king is in check
97	 *
98	 * @param board - Board to check
99	 * @returns true if king is in check
100	 */
101	export function isKingInCheck(board: InternalBoard): boolean {
102	    const kingBitboard = board.turn === InternalColor.WHITE ? board.whiteKing : board.blackKing;
103	
104	    if (kingBitboard === 0n) {
105	        return false; // No king (shouldn't happen in real game)
106	    }
107	
108	    const kingSquare = getLowestSetBit(kingBitboard);
109	    const opponentColor = board.turn === InternalColor.WHITE ? InternalColor.BLACK : InternalColor.WHITE;
110	
111	    return isSquareAttacked(board, kingSquare, opponentColor);
112	}
113	
114	/**
115	 * Get all squares attacked by a specific color
116	 *
117	 * @param board - Board to check
118	 * @param attackerColor - Color of attacking pieces
119	 * @returns Bitboard of all attacked squares
120	 */
121	export function getAttackedSquares(board: InternalBoard, attackerColor: InternalColor): Bitboard {
122	    let attacked = 0n;
123	
124	    // Pawn attacks
125	    const pawns = attackerColor === InternalColor.WHITE ? board.whitePawns : board.blackPawns;
126	    if (attackerColor === InternalColor.WHITE) {
127	        // White pawns attack north-east and north-west
128	        attacked |= ((pawns & 0xFEFEFEFEFEFEFEFEn) << 9n); // North-East (not on H-file)
129	        attacked |= ((pawns & 0x7F7F7F7F7F7F7F7Fn) << 7n); // North-West (not on A-file)
130	    } else {
131	        // Black pawns attack south-east and south-west
132	        attacked |= ((pawns & 0xFEFEFEFEFEFEFEFEn) >> 7n); // South-East (not on H-file)
133	        attacked |= ((pawns & 0x7F7F7F7F7F7F7F7Fn) >> 9n); // South-West (not on A-file)
134	    }
135	
136	    // Knight attacks
137	    const knights = attackerColor === InternalColor.WHITE ? board.whiteKnights : board.blackKnights;
138	    let knightsBB = knights;
139	    while (knightsBB !== 0n) {
140	        const sq = getLowestSetBit(knightsBB);
141	        attacked |= getKnightAttacks(sq);
142	        knightsBB &= knightsBB - 1n; // Clear lowest bit
143	    }
144	
145	    // Bishop attacks
146	    const bishops = attackerColor === InternalColor.WHITE ? board.whiteBishops : board.blackBishops;
147	    let bishopsBB = bishops;
148	    while (bishopsBB !== 0n) {
149	        const sq = getLowestSetBit(bishopsBB);
150	        attacked |= getBishopAttacks(sq, board.allPieces);
151	        bishopsBB &= bishopsBB - 1n;
152	    }
153	
154	    // Rook attacks
155	    const rooks = attackerColor === InternalColor.WHITE ? board.whiteRooks : board.blackRooks;
156	    let rooksBB = rooks;
157	    while (rooksBB !== 0n) {
158	        const sq = getLowestSetBit(rooksBB);
159	        attacked |= getRookAttacks(sq, board.allPieces);
160	        rooksBB &= rooksBB - 1n;
161	    }
162	
163	    // Queen attacks
164	    const queens = attackerColor === InternalColor.WHITE ? board.whiteQueens : board.blackQueens;
165	    let queensBB = queens;
166	    while (queensBB !== 0n) {
167	        const sq = getLowestSetBit(queensBB);
168	        attacked |= getQueenAttacks(sq, board.allPieces);
169	        queensBB &= queensBB - 1n;
170	    }
171	
172	    // King attacks
173	    const king = attackerColor === InternalColor.WHITE ? board.whiteKing : board.blackKing;
174	    if (king !== 0n) {
175	        const kingSquare = getLowestSetBit(king);
176	        attacked |= getKingAttacks(kingSquare);
177	    }
178	
179	    return attacked;
180	}
181	
182	/**
183	 * Get all pieces attacking a specific square
184	 *
185	 * @param board - Board to check
186	 * @param square - Square being attacked
187	 * @param attackerColor - Color of attacking pieces
188	 * @returns Bitboard of all pieces attacking the square
189	 */
190	export function getAttackers(
191	    board: InternalBoard,
192	    square: SquareIndex,
193	    attackerColor: InternalColor
194	): Bitboard {
195	    let attackers = 0n;
196	
197	    // Pawn attackers
198	    const pawnAttackOrigins = attackerColor === InternalColor.WHITE
199	        ? getBlackPawnAttacks(square)
200	        : getWhitePawnAttacks(square);
201	    const pawns = attackerColor === InternalColor.WHITE ? board.whitePawns : board.blackPawns;
202	    attackers |= pawnAttackOrigins & pawns;
203	
204	    // Knight attackers
205	    const knightAttacks = getKnightAttacks(square);
206	    const knights = attackerColor === InternalColor.WHITE ? board.whiteKnights : board.blackKnights;
207	    attackers |= knightAttacks & knights;
208	
209	    // Bishop and queen diagonal attackers
210	    const bishopAttacks = getBishopAttacks(square, board.allPieces);
211	    const bishops = attackerColor === InternalColor.WHITE ? board.whiteBishops : board.blackBishops;
212	    const queens = attackerColor === InternalColor.WHITE ? board.whiteQueens : board.blackQueens;
213	    attackers |= bishopAttacks & (bishops | queens);
214	
215	    // Rook and queen straight attackers
216	    const rookAttacks = getRookAttacks(square, board.allPieces);
217	    const rooks = attackerColor === InternalColor.WHITE ? board.whiteRooks : board.blackRooks;
218	    attackers |= rookAttacks & (rooks | queens);
219	
220	    // King attackers
221	    const kingAttacks = getKingAttacks(square);
222	    const king = attackerColor === InternalColor.WHITE ? board.whiteKing : board.blackKing;
223	    attackers |= kingAttacks & king;
224	
225	    return attackers;
226	}
