229	 * Check if moving a piece would leave the king in check (pinned piece detection)
230	 *
231	 * @param board - Board state
232	 * @param from - Square piece is moving from
233	 * @param to - Square piece is moving to
234	 * @returns true if move would leave king in check
235	 */
236	export function wouldLeaveKingInCheck(
237	    board: InternalBoard,
238	    from: SquareIndex,
239	    to: SquareIndex
240	): boolean {
241	    const piece = board.mailbox[from];
242	    const capturedPiece = board.mailbox[to];
243	    const color = board.turn;
244	
245	    // Make the move temporarily
246	    board.mailbox[from] = Piece.EMPTY;
247	    board.mailbox[to] = piece;
248	
249	    // Update bitboards
250	    const fromBit = 1n << BigInt(from);
251	    const toBit = 1n << BigInt(to);
252	    const moveBits = fromBit | toBit;
253	
254	    // Save original bitboard state
255	    let originalPieceBB: Bitboard;
256	    let originalCapturedBB: Bitboard | null = null;
257	
258	    // Update piece bitboard
259	    switch (piece) {
260	        case Piece.WHITE_PAWN:
261	            originalPieceBB = board.whitePawns;
262	            board.whitePawns = (board.whitePawns & ~fromBit) | toBit;
263	            break;
264	        case Piece.WHITE_KNIGHT:
265	            originalPieceBB = board.whiteKnights;
266	            board.whiteKnights = (board.whiteKnights & ~fromBit) | toBit;
267	            break;
268	        case Piece.WHITE_BISHOP:
269	            originalPieceBB = board.whiteBishops;
270	            board.whiteBishops = (board.whiteBishops & ~fromBit) | toBit;
271	            break;
272	        case Piece.WHITE_ROOK:
273	            originalPieceBB = board.whiteRooks;
274	            board.whiteRooks = (board.whiteRooks & ~fromBit) | toBit;
275	            break;
276	        case Piece.WHITE_QUEEN:
277	            originalPieceBB = board.whiteQueens;
278	            board.whiteQueens = (board.whiteQueens & ~fromBit) | toBit;
279	            break;
280	        case Piece.WHITE_KING:
281	            originalPieceBB = board.whiteKing;
282	            board.whiteKing = (board.whiteKing & ~fromBit) | toBit;
283	            break;
284	        case Piece.BLACK_PAWN:
285	            originalPieceBB = board.blackPawns;
286	            board.blackPawns = (board.blackPawns & ~fromBit) | toBit;
287	            break;
288	        case Piece.BLACK_KNIGHT:
289	            originalPieceBB = board.blackKnights;
290	            board.blackKnights = (board.blackKnights & ~fromBit) | toBit;
291	            break;
292	        case Piece.BLACK_BISHOP:
293	            originalPieceBB = board.blackBishops;
294	            board.blackBishops = (board.blackBishops & ~fromBit) | toBit;
295	            break;
296	        case Piece.BLACK_ROOK:
297	            originalPieceBB = board.blackRooks;
298	            board.blackRooks = (board.blackRooks & ~fromBit) | toBit;
299	            break;
300	        case Piece.BLACK_QUEEN:
301	            originalPieceBB = board.blackQueens;
302	            board.blackQueens = (board.blackQueens & ~fromBit) | toBit;
303	            break;
304	        case Piece.BLACK_KING:
305	            originalPieceBB = board.blackKing;
306	            board.blackKing = (board.blackKing & ~fromBit) | toBit;
307	            break;
308	        default:
309	            originalPieceBB = 0n;
310	    }
311	
312	    // Update captured piece bitboard if there's a capture
313	    if (capturedPiece !== Piece.EMPTY) {
314	        switch (capturedPiece) {
315	            case Piece.WHITE_PAWN:
316	                originalCapturedBB = board.whitePawns;
317	                board.whitePawns &= ~toBit;
318	                break;
319	            case Piece.WHITE_KNIGHT:
320	                originalCapturedBB = board.whiteKnights;
321	                board.whiteKnights &= ~toBit;
322	                break;
323	            case Piece.WHITE_BISHOP:
324	                originalCapturedBB = board.whiteBishops;
325	                board.whiteBishops &= ~toBit;
326	                break;
327	            case Piece.WHITE_ROOK:
328	                originalCapturedBB = board.whiteRooks;
329	                board.whiteRooks &= ~toBit;
330	                break;
331	            case Piece.WHITE_QUEEN:
332	                originalCapturedBB = board.whiteQueens;
333	                board.whiteQueens &= ~toBit;
334	                break;
335	            case Piece.BLACK_PAWN:
336	                originalCapturedBB = board.blackPawns;
337	                board.blackPawns &= ~toBit;
338	                break;
339	            case Piece.BLACK_KNIGHT:
340	                originalCapturedBB = board.blackKnights;
341	                board.blackKnights &= ~toBit;
342	                break;
343	            case Piece.BLACK_BISHOP:
344	                originalCapturedBB = board.blackBishops;
345	                board.blackBishops &= ~toBit;
346	                break;
347	            case Piece.BLACK_ROOK:
348	                originalCapturedBB = board.blackRooks;
349	                board.blackRooks &= ~toBit;
350	                break;
351	            case Piece.BLACK_QUEEN:
352	                originalCapturedBB = board.blackQueens;
353	                board.blackQueens &= ~toBit;
354	                break;
355	        }
356	    }
357	
358	    // Update composite bitboards
359	    const originalWhitePieces = board.whitePieces;
360	    const originalBlackPieces = board.blackPieces;
361	    const originalAllPieces = board.allPieces;
362	
363	    board.whitePieces = board.whitePawns | board.whiteKnights | board.whiteBishops |
364	                        board.whiteRooks | board.whiteQueens | board.whiteKing;
365	    board.blackPieces = board.blackPawns | board.blackKnights | board.blackBishops |
366	                        board.blackRooks | board.blackQueens | board.blackKing;
367	    board.allPieces = board.whitePieces | board.blackPieces;
368	
369	    // Check if king is in check
370	    const inCheck = isKingInCheck(board);
371	
372	    // Undo the move
373	    board.mailbox[from] = piece;
374	    board.mailbox[to] = capturedPiece;
375	
376	    // Restore bitboards
377	    switch (piece) {
378	        case Piece.WHITE_PAWN: board.whitePawns = originalPieceBB; break;
379	        case Piece.WHITE_KNIGHT: board.whiteKnights = originalPieceBB; break;
380	        case Piece.WHITE_BISHOP: board.whiteBishops = originalPieceBB; break;
381	        case Piece.WHITE_ROOK: board.whiteRooks = originalPieceBB; break;
382	        case Piece.WHITE_QUEEN: board.whiteQueens = originalPieceBB; break;
383	        case Piece.WHITE_KING: board.whiteKing = originalPieceBB; break;
384	        case Piece.BLACK_PAWN: board.blackPawns = originalPieceBB; break;
385	        case Piece.BLACK_KNIGHT: board.blackKnights = originalPieceBB; break;
386	        case Piece.BLACK_BISHOP: board.blackBishops = originalPieceBB; break;
387	        case Piece.BLACK_ROOK: board.blackRooks = originalPieceBB; break;
388	        case Piece.BLACK_QUEEN: board.blackQueens = originalPieceBB; break;
389	        case Piece.BLACK_KING: board.blackKing = originalPieceBB; break;
390	    }
391	
392	    if (originalCapturedBB !== null) {
393	        switch (capturedPiece) {
394	            case Piece.WHITE_PAWN: board.whitePawns = originalCapturedBB; break;
395	            case Piece.WHITE_KNIGHT: board.whiteKnights = originalCapturedBB; break;
396	            case Piece.WHITE_BISHOP: board.whiteBishops = originalCapturedBB; break;
397	            case Piece.WHITE_ROOK: board.whiteRooks = originalCapturedBB; break;
398	            case Piece.WHITE_QUEEN: board.whiteQueens = originalCapturedBB; break;
399	            case Piece.BLACK_PAWN: board.blackPawns = originalCapturedBB; break;
400	            case Piece.BLACK_KNIGHT: board.blackKnights = originalCapturedBB; break;
401	            case Piece.BLACK_BISHOP: board.blackBishops = originalCapturedBB; break;
402	            case Piece.BLACK_ROOK: board.blackRooks = originalCapturedBB; break;
403	            case Piece.BLACK_QUEEN: board.blackQueens = originalCapturedBB; break;
404	        }
405	    }
406	
407	    board.whitePieces = originalWhitePieces;
408	    board.blackPieces = originalBlackPieces;
409	    board.allPieces = originalAllPieces;
410	
411	    return inCheck;
412	}
