1	/**
2	 * FEN (Forsyth-Edwards Notation) parser and formatter
3	 *
4	 * FEN format: pieces turn castling enPassant halfMove fullMove
5	 * Example: rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1
6	 */
7	
8	import { InternalBoard, Piece, InternalColor, SquareIndex } from '../types';
9	import { createEmptyBoard, setPiece } from '../core/Board';
10	import { isKingInCheck } from '../core/AttackDetector';
11	import { computeZobristHash } from '../core/zobrist';
12	import { squareToIndex, indexToSquare } from './conversion';
13	
14	const FEN_CASTLING_RE = /^(-|[KQkq]{1,4})$/;
15	const FEN_EN_PASSANT_RE = /^(-|[a-h][36])$/;
16	
17	/**
18	 * Parse a FEN string into an internal board
19	 *
20	 * @param fen - FEN string
21	 * @returns Internal board representation
22	 */
23	export function parseFEN(fen: string): InternalBoard {
24	    const parts = fen.trim().split(/\s+/);
25	
26	    if (parts.length !== 6) {
27	        throw new Error(`Invalid FEN: expected 6 parts, got ${parts.length}`);
28	    }
29	
30	    const [piecePlacement, activeColor, castling, enPassant, halfMove, fullMove] = parts;
31	
32	    const board = createEmptyBoard();
33	
34	    // Parse piece placement (ranks 8 to 1, separated by /)
35	    const ranks = piecePlacement.split('/');
36	    if (ranks.length !== 8) {
37	        throw new Error(`Invalid FEN: expected 8 ranks, got ${ranks.length}`);
38	    }
39	
40	    for (let rank = 0; rank < 8; rank++) {
41	        const rankStr = ranks[rank];
42	        let file = 0;
43	
44	        for (const char of rankStr) {
45	            if (char >= '1' && char <= '8') {
46	                // Empty squares
47	                file += parseInt(char, 10);
48	            } else {
49	                // Piece
50	                const piece = fenCharToPiece(char);
51	                if (piece === null) {
52	                    throw new Error(`Invalid FEN: unknown piece character '${char}'`);
53	                }
54	
55	                // Convert rank/file to square index
56	                // FEN ranks go from 8 to 1 (top to bottom)
57	                // Our indices go from 0 to 63 (bottom to top, left to right)
58	                const squareIndex = (7 - rank) * 8 + file;
59	                setPiece(board, squareIndex as SquareIndex, piece);
60	                file++;
61	            }
62	        }
63	
64	        if (file !== 8) {
65	            throw new Error(`Invalid FEN: rank ${8 - rank} has ${file} files instead of 8`);
66	        }
67	    }
68	
69	    // Validate piece placement has exactly one king of each color
70	    let whiteKings = 0;
71	    let blackKings = 0;
72	    for (const p of board.mailbox) {
73	        if (p === Piece.WHITE_KING) whiteKings++;
74	        if (p === Piece.BLACK_KING) blackKings++;
75	    }
76	    if (whiteKings !== 1 || blackKings !== 1) {
77	        throw new Error(`Invalid FEN: expected exactly one white king and one black king`);
78	    }
79	
80	    // Parse active color
81	    if (activeColor === 'w') {
82	        board.turn = InternalColor.WHITE;
83	    } else if (activeColor === 'b') {
84	        board.turn = InternalColor.BLACK;
85	    } else {
86	        throw new Error(`Invalid FEN: unknown active color '${activeColor}'`);
87	    }
88	
89	    // Validate castling rights string
90	    if (!FEN_CASTLING_RE.test(castling)) {
91	        throw new Error(`Invalid FEN: invalid castling rights '${castling}'`);
92	    }
93	    if (castling !== '-') {
94	        const unique = new Set(castling.split(''));
95	        if (unique.size !== castling.length) {
96	            throw new Error(`Invalid FEN: duplicate castling rights '${castling}'`);
97	        }
98	    }
99	
100	    // Parse castling rights
101	    board.castlingRights.whiteShort = castling.includes('K');
102	    board.castlingRights.whiteLong = castling.includes('Q');
103	    board.castlingRights.blackShort = castling.includes('k');
104	    board.castlingRights.blackLong = castling.includes('q');
105	
106	    // Parse en passant square
107	    if (!FEN_EN_PASSANT_RE.test(enPassant)) {
108	        throw new Error(`Invalid FEN: invalid en passant square '${enPassant}'`);
109	    }
110	    if (enPassant !== '-') {
111	        // enPassant is lowercase by regex; squareToIndex expects uppercase.
112	        board.enPassantSquare = squareToIndex(enPassant.toUpperCase());
113	    }
114	
115	    // Parse half-move clock (for 50-move rule)
116	    board.halfMoveClock = parseInt(halfMove, 10);
117	    if (isNaN(board.halfMoveClock)) {
118	        throw new Error(`Invalid FEN: invalid half-move clock '${halfMove}'`);
119	    }
120	    if (board.halfMoveClock < 0) {
121	        throw new Error(`Invalid FEN: half-move clock must be >= 0`);
122	    }
123	
124	    // Parse full move number
125	    board.fullMoveNumber = parseInt(fullMove, 10);
126	    if (isNaN(board.fullMoveNumber)) {
127	        throw new Error(`Invalid FEN: invalid full move number '${fullMove}'`);
128	    }
129	    if (board.fullMoveNumber < 1) {
130	        throw new Error(`Invalid FEN: full move number must be >= 1`);
131	    }
132	
133	    // Keep zobristHash consistent for TT caching.
134	    board.zobristHash = computeZobristHash(board);
135	
136	    // Basic legality: it cannot be the case that the side who is NOT to move is in check.
137	    // Example: a FEN that has "w" to move while black is already in check is not a reachable
138	    // game state in standard chess.
139	    // (The side in check must be the side to move.)
140	    const notToMove = board.turn === InternalColor.WHITE ? InternalColor.BLACK : InternalColor.WHITE;
141	    const originalTurn = board.turn;
142	    try {
143	        board.turn = notToMove;
144	        if (isKingInCheck(board)) {
145	            const side = notToMove === InternalColor.WHITE ? 'white' : 'black';
146	            throw new Error(`Invalid FEN: ${side} is in check but it is not ${side}'s turn`);
147	        }
148	    } finally {
149	        board.turn = originalTurn;
150	    }
151	
152	    return board;
153	}
154	
155	/**
156	 * Validate a FEN string.
157	 *
158	 * This is intended for user-provided input. It throws with a descriptive message
159	 * when the FEN is invalid.
160	 */
161	export function validateFEN(fen: string): void {
162	    // parseFEN already performs full validation and throws on any error.
163	    parseFEN(fen);
164	}
165	
166	/**
167	 * Convert an internal board to a FEN string
168	 *
169	 * @param board - Internal board
170	 * @returns FEN string
171	 */
172	export function toFEN(board: InternalBoard): string {
173	    const parts: string[] = [];
174	
175	    // 1. Piece placement (ranks 8 to 1)
176	    const rankStrings: string[] = [];
177	    for (let rank = 7; rank >= 0; rank--) {
178	        let rankStr = '';
179	        let emptyCount = 0;
180	
181	        for (let file = 0; file < 8; file++) {
182	            const squareIndex = rank * 8 + file;
183	            const piece = board.mailbox[squareIndex];
184	
185	            if (piece === Piece.EMPTY) {
186	                emptyCount++;
187	            } else {
188	                if (emptyCount > 0) {
189	                    rankStr += emptyCount.toString();
190	                    emptyCount = 0;
191	                }
192	                rankStr += pieceToFenChar(piece);
193	            }
194	        }
195	
196	        if (emptyCount > 0) {
197	            rankStr += emptyCount.toString();
198	        }
199	
200	        rankStrings.push(rankStr);
201	    }
202	    parts.push(rankStrings.join('/'));
203	
204	    // 2. Active color
205	    parts.push(board.turn === InternalColor.WHITE ? 'w' : 'b');
206	
207	    // 3. Castling rights
208	    let castling = '';
209	    if (board.castlingRights.whiteShort) castling += 'K';
210	    if (board.castlingRights.whiteLong) castling += 'Q';
211	    if (board.castlingRights.blackShort) castling += 'k';
212	    if (board.castlingRights.blackLong) castling += 'q';
213	    parts.push(castling || '-');
214	
215	    // 4. En passant square
216	    if (board.enPassantSquare !== null) {
217	        parts.push(indexToSquare(board.enPassantSquare).toLowerCase());
218	    } else {
219	        parts.push('-');
220	    }
221	
222	    // 5. Half-move clock
223	    parts.push(board.halfMoveClock.toString());
224	
225	    // 6. Full move number
226	    parts.push(board.fullMoveNumber.toString());
227	
228	    return parts.join(' ');
229	}
230	
231	/**
232	 * Convert a FEN character to a piece enum
233	 *
234	 * @param char - FEN character (K, Q, R, B, N, P, k, q, r, b, n, p)
235	 * @returns Piece enum value or null if invalid
236	 */
237	function fenCharToPiece(char: string): Piece | null {
238	    switch (char) {
239	        case 'K': return Piece.WHITE_KING;
240	        case 'Q': return Piece.WHITE_QUEEN;
241	        case 'R': return Piece.WHITE_ROOK;
242	        case 'B': return Piece.WHITE_BISHOP;
243	        case 'N': return Piece.WHITE_KNIGHT;
244	        case 'P': return Piece.WHITE_PAWN;
245	        case 'k': return Piece.BLACK_KING;
246	        case 'q': return Piece.BLACK_QUEEN;
247	        case 'r': return Piece.BLACK_ROOK;
248	        case 'b': return Piece.BLACK_BISHOP;
249	        case 'n': return Piece.BLACK_KNIGHT;
250	        case 'p': return Piece.BLACK_PAWN;
251	        default: return null;
252	    }
253	}
254	
255	/**
256	 * Convert a piece enum to a FEN character
257	 *
258	 * @param piece - Piece enum value
259	 * @returns FEN character
260	 */
261	function pieceToFenChar(piece: Piece): string {
262	    switch (piece) {
263	        case Piece.WHITE_KING: return 'K';
264	        case Piece.WHITE_QUEEN: return 'Q';
265	        case Piece.WHITE_ROOK: return 'R';
266	        case Piece.WHITE_BISHOP: return 'B';
267	        case Piece.WHITE_KNIGHT: return 'N';
268	        case Piece.WHITE_PAWN: return 'P';
269	        case Piece.BLACK_KING: return 'k';
270	        case Piece.BLACK_QUEEN: return 'q';
271	        case Piece.BLACK_ROOK: return 'r';
272	        case Piece.BLACK_BISHOP: return 'b';
273	        case Piece.BLACK_KNIGHT: return 'n';
274	        case Piece.BLACK_PAWN: return 'p';
275	        default: return '';
276	    }
277	}
278	
279	/**
280	 * Get FEN for starting position
281	 *
282	 * @returns FEN string for standard chess starting position
283	 */
284	export function getStartingFEN(): string {
285	    return 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';
286	}
