1	/**
2	 * Board-related types for js-chess-engine
3	 */
4	
5	// ==================== Public API Types ====================
6	
7	/**
8	 * Color of a piece or player
9	 */
10	export type Color = 'white' | 'black';
11	
12	/**
13	 * Piece notation using standard chess symbols
14	 * Uppercase = white, lowercase = black
15	 */
16	export type PieceSymbol = 'K' | 'Q' | 'R' | 'B' | 'N' | 'P' | 'k' | 'q' | 'r' | 'b' | 'n' | 'p';
17	
18	/**
19	 * Piece type (without color)
20	 */
21	export type PieceType = 'king' | 'queen' | 'rook' | 'bishop' | 'knight' | 'pawn';
22	
23	/**
24	 * Square notation (A1-H8)
25	 */
26	export type Square = string;
27	
28	/**
29	 * Column notation (A-H)
30	 */
31	export type Column = 'A' | 'B' | 'C' | 'D' | 'E' | 'F' | 'G' | 'H';
32	
33	/**
34	 * Row notation (1-8)
35	 */
36	export type Row = '1' | '2' | '3' | '4' | '5' | '6' | '7' | '8';
37	
38	/**
39	 * Castling rights configuration
40	 */
41	export interface CastlingRights {
42	    whiteShort: boolean;
43	    blackShort: boolean;
44	    whiteLong: boolean;
45	    blackLong: boolean;
46	}
47	
48	/**
49	 * Public board configuration (API format)
50	 * Maps square strings (e.g., "E1", "A8") to piece symbols
51	 */
52	export interface BoardConfig {
53	    pieces: Record<Square, PieceSymbol>;
54	    turn: Color;
55	    isFinished: boolean;
56	    check: boolean;
57	    checkMate: boolean;
58	    staleMate: boolean;
