1	/**
2	 * Minimal, fast negamax alpha-beta search.
3	 *
4	 * Goals:
5	 * - Browser-friendly: bounded work, no expensive root guardrails.
6	 * - Deterministic.
7	 * - Uses TT + basic move ordering for practical strength.
8	 */
9	
10	import { InternalBoard, InternalMove, InternalColor, MoveFlag, Piece } from '../types';
11	import { generateLegalMoves, generatePseudoLegalMoves, applyMoveComplete } from '../core/MoveGenerator';
12	import { copyBoard } from '../core/Board';
13	import { isKingInCheck, isSquareAttacked } from '../core/AttackDetector';
14	import { getLowestSetBit } from '../utils/conversion';
15	import { Evaluator, SCORE_MAX, SCORE_MIN } from './Evaluator';
16	import { Score, SearchResult } from '../types/ai.types';
17	import { TranspositionTable, TTEntryType } from './TranspositionTable';
18	import { KillerMoves, MoveSelector } from './MoveOrdering';
19	
20	// Keep within evaluator bounds.
21	const INF: Score = SCORE_MAX;
22	
23	export class Search {
24	    private nodesSearched = 0;
25	
26	    private qMaxDepth = 4;
27	    private checkExtension = true;
28	
29	    private transpositionTable: TranspositionTable | null;
30	    private killerMoves: KillerMoves;
31	
32	    constructor(ttSizeMB: number = 16) {
33	        this.transpositionTable = ttSizeMB > 0 ? new TranspositionTable(ttSizeMB) : null;
34	        this.killerMoves = new KillerMoves();
35	    }
36	
37	    clear(): void {
38	        this.transpositionTable?.clear();
39	        this.killerMoves.clear();
40	    }
41	
42	    findBestMove(
43	        board: InternalBoard,
44	        baseDepth: number,
45	        qMaxDepth: number = 4,
46	        checkExtension: boolean = true,
47	        options: { analysis?: boolean; randomness?: number } = {}
48	    ): SearchResult | null {
49	        this.qMaxDepth = qMaxDepth;
50	        this.checkExtension = checkExtension;
51	        this.nodesSearched = 0;
52	        this.transpositionTable?.newSearch();
53	        this.killerMoves.clear();
54	
55	        const analysis = options.analysis ?? false;
56	        const randomness = options.randomness ?? 0;
57	
58	        const moves = generateLegalMoves(board);
59	        if (moves.length === 0) {
60	            const inCheck = isKingInCheck(board);
61	            const score = inCheck ? (SCORE_MIN + 0) : 0;
62	            return { move: null as any, score, depth: 0, nodesSearched: this.nodesSearched };
63	        }
64	
65	        let bestMove: InternalMove | null = null;
66	        let bestScore: Score = SCORE_MIN;
67	        let scoredMoves: Array<{ move: InternalMove; score: Score }> | undefined;
68	
69	        // Iterative deepening: search depth 1..baseDepth.
70	        // Populates TT progressively for better move ordering at deeper levels.
71	        const ASPIRATION_DELTA = 25;
72	
73	        for (let d = 1; d <= baseDepth; d++) {
74	            // Collect root scores at final depth: for analysis or randomness (both need accurate scores)
75	            const collectScores = (d === baseDepth) && (randomness > 0 || analysis);
76	
77	            // Aspiration window: use previous iteration's score for d >= 4
78	            let alpha: Score = SCORE_MIN;
79	            let beta: Score = SCORE_MAX;
80	            let delta = ASPIRATION_DELTA;
81	            if (d >= 4 && bestScore > SCORE_MIN && bestScore < SCORE_MAX) {
82	                alpha = (bestScore - delta) as Score;
83	                beta = (bestScore + delta) as Score;
84	            }
85	
86	            // Aspiration retry loop
87	            let iterBestMove: InternalMove | null = null;
88	            let iterBestScore: Score = SCORE_MIN;
89	            let iterScoredMoves: Array<{ move: InternalMove; score: Score }> | null = null;
90	
91	            while (true) {
92	                const pvMove = this.transpositionTable?.getBestMove(board.zobristHash) ?? null;
93	                const selector = new MoveSelector(moves, pvMove, this.killerMoves, 0);
94	
95	                iterScoredMoves = collectScores ? [] : null;
96	                iterBestMove = null;
97	                iterBestScore = SCORE_MIN;
98	                let iterAlpha = alpha;
99	
100	                let move: InternalMove | null;
101	                let moveIndex = 0;
102	                while ((move = selector.pickNext()) !== null) {
103	                    if ((move.flags & MoveFlag.PROMOTION) && move.promotionPiece) {
104	                        const isQueenPromotion =
105	                            move.promotionPiece === Piece.WHITE_QUEEN ||
106	                            move.promotionPiece === Piece.BLACK_QUEEN;
107	                        if (!isQueenPromotion) continue;
108	                    }
109	
110	                    const child = copyBoard(board);
111	                    applyMoveComplete(child, move);
112	
113	                    const extension = (this.checkExtension && child.isCheck) ? 1 : 0;
114	
115	                    let score: Score;
116	                    if (moveIndex === 0) {
117	                        score = -this.negamax(child, d - 1 + extension, -beta, -iterAlpha, 1);
118	                    } else {
119	                        // PVS: zero window search first
120	                        score = -this.negamax(child, d - 1 + extension, -iterAlpha - 1, -iterAlpha, 1);
121	                        // Re-search with full window if it beats alpha
122	                        if (score > iterAlpha && score < beta) {
123	                            score = -this.negamax(child, d - 1 + extension, -beta, -iterAlpha, 1);
124	                        }
125	                    }
126	                    moveIndex++;
127	
128	                    if (iterScoredMoves) {
129	                        iterScoredMoves.push({ move, score });
130	                    }
131	
132	                    if (score > iterBestScore || iterBestMove === null) {
133	                        iterBestScore = score;
134	                        iterBestMove = move;
135	                    }
136	
137	                    if (score > iterAlpha) iterAlpha = score;
138	                    if (iterAlpha >= beta) break;
139	                }
140	
141	                // Check aspiration window result
142	                if (d >= 4 && (alpha > SCORE_MIN || beta < SCORE_MAX)) {
143	                    if (iterBestScore <= alpha) {
144	                        // Fail low - widen alpha
145	                        delta *= 2;
146	                        alpha = (delta > 400) ? SCORE_MIN : Math.max(SCORE_MIN, alpha - delta) as Score;
147	                        continue;
148	                    }
149	                    if (iterBestScore >= beta) {
150	                        // Fail high - widen beta
151	                        delta *= 2;
152	                        beta = (delta > 400) ? SCORE_MAX : Math.min(SCORE_MAX, beta + delta) as Score;
153	                        continue;
154	                    }
155	                }
156	                break;
157	            }
158	
159	            if (iterScoredMoves) {
160	                iterScoredMoves.sort((a, b) => b.score - a.score);
161	                scoredMoves = iterScoredMoves;
162	                // Derive best move from the sorted array — more reliable than iterBestMove
163	                // because iterAlpha shifts during the loop when disablePVS is true.
164	                if (iterScoredMoves.length > 0) {
165	                    bestMove = iterScoredMoves[0].move;
166	                    bestScore = iterScoredMoves[0].score;
167	                }
168	            } else if (iterBestMove) {
169	                bestMove = iterBestMove;
170	                bestScore = iterBestScore;
171	            }
172	        }
173	
174	        // Apply randomness: pick randomly among moves within `randomness` cp of the best score.
175	        // Locked to the same quality tier as the best move: if the best move is a capture,
176	        // only randomize among captures — never pick a quiet move over a winning capture.
177	        if (randomness > 0 && scoredMoves && scoredMoves.length > 1) {
178	            const threshold = bestScore - randomness;
179	            let candidates = scoredMoves.filter(e => e.score >= threshold);
180	            if (candidates.length > 1) {
181	                const bestIsCapture = !!(scoredMoves[0].move.flags & MoveFlag.CAPTURE);
182	                if (bestIsCapture) {
183	                    const captureCandidates = candidates.filter(e => e.move.flags & MoveFlag.CAPTURE);
184	                    if (captureCandidates.length > 0) candidates = captureCandidates;
185	                }
186	                bestMove = candidates[Math.floor(Math.random() * candidates.length)].move;
187	            }
188	        }
189	
190	        return bestMove
191	            ? { move: bestMove, score: bestScore, depth: baseDepth, nodesSearched: this.nodesSearched, scoredMoves }
192	            : null;
193	    }
194	
195	    private negamax(
196	        board: InternalBoard,
197	        depth: number,
198	        alpha: Score,
199	        beta: Score,
200	        ply: number
201	    ): Score {
202	        this.nodesSearched++;
203	
204	            if (depth <= 0) {
205	                return this.quiescence(board, alpha, beta, ply, 0);
206	            }
207	
208	            // TT probe
209	            const tt = this.transpositionTable;
210	            const hash = board.zobristHash;
211	            let ttMove: InternalMove | null = null;
212	
213	            if (tt) {
214	                const entry = tt.probe(hash, depth, alpha, beta, ply);
215	                if (entry) {
216	                    ttMove = entry.bestMove;
217	                    if (entry.type === TTEntryType.EXACT) return entry.score;
218	                    if (entry.type === TTEntryType.LOWER_BOUND && entry.score >= beta) return entry.score;
219	                    if (entry.type === TTEntryType.UPPER_BOUND && entry.score <= alpha) return entry.score;
220	                }
221	            }
222	
223	            const moves = generatePseudoLegalMoves(board);
224	            const selector = new MoveSelector(moves, ttMove, this.killerMoves, ply);
225	
226	            const startAlpha = alpha;
227	            let bestScore: Score = -INF;
228	            let bestMove: InternalMove | null = null;
229	            let legalMoveCount = 0;
230	            let move: InternalMove | null;
231	
232	            while ((move = selector.pickNext()) !== null) {
233	                if ((move.flags & MoveFlag.PROMOTION) && move.promotionPiece) {
234	                    const isQueenPromotion =
235	                        move.promotionPiece === Piece.WHITE_QUEEN ||
236	                        move.promotionPiece === Piece.BLACK_QUEEN;
237	                    if (!isQueenPromotion) continue;
238	                }
239	
240	                const child = copyBoard(board);
241	                applyMoveComplete(child, move);
242	
243	                // Skip illegal moves (own king left in check)
244	                if (this.isIllegalMove(child)) continue;
245	
246	                legalMoveCount++;
247	                const extension = (this.checkExtension && child.isCheck) ? 1 : 0;
248	
249	                let score: Score;
250	                if (legalMoveCount === 1) {
251	                    // First move (PV move): search with full window
252	                    score = -this.negamax(child, depth - 1 + extension, -beta, -alpha, ply + 1);
253	                } else {
254	                    // PVS: search with zero window first
255	                    score = -this.negamax(child, depth - 1 + extension, -alpha - 1, -alpha, ply + 1);
256	                    // Re-search with full window if it beats alpha
257	                    if (score > alpha && score < beta) {
258	                        score = -this.negamax(child, depth - 1 + extension, -beta, -alpha, ply + 1);
259	                    }
260	                }
261	
262	                if (score > bestScore || bestMove === null) {
263	                    bestScore = score;
264	                    bestMove = move;
265	                }
266	
267	                if (score > alpha) alpha = score;
268	                if (alpha >= beta) {
269	                    this.killerMoves.store(move, ply);
270	                    break;
271	                }
272	            }
273	
274	            // No legal moves: checkmate or stalemate
275	            if (legalMoveCount === 0) {
276	                if (isKingInCheck(board)) return SCORE_MIN + ply;
277	                return 0;
278	            }
279	
280	            // TT store
281	            if (tt && bestMove) {
282	                let type = TTEntryType.EXACT;
283	                if (bestScore <= startAlpha) type = TTEntryType.UPPER_BOUND;
284	                else if (bestScore >= beta) type = TTEntryType.LOWER_BOUND;
285	
286	                tt.store(hash, depth, bestScore, type, bestMove, ply);
287	            }
288	
289	            return bestScore;
290	        }
291	
292	    private quiescence(
293	        board: InternalBoard,
294	        alpha: Score,
295	        beta: Score,
296	        ply: number,
297	        qDepth: number
298	    ): Score {
299	        this.nodesSearched++;
300	
301	        // Stand-pat: evaluate before move generation
302	        const standPat = Evaluator.evaluate(board, board.turn, ply);
303	        if (standPat >= beta) return standPat;
304	        if (standPat > alpha) alpha = standPat;
305	        if (qDepth >= this.qMaxDepth) return standPat;
306	
307	        // Generate pseudo-legal moves, collect forcing (captures + promotions)
308	        const allMoves = generatePseudoLegalMoves(board);
309	        const forcingMask = MoveFlag.CAPTURE | MoveFlag.PROMOTION;
310	        const forcing: InternalMove[] = [];
311	        for (let i = 0; i < allMoves.length; i++) {
312	            if (allMoves[i].flags & forcingMask) forcing.push(allMoves[i]);
313	        }
314	
315	        const tt = this.transpositionTable;
316	        const ttMove = tt ? tt.getBestMove(board.zobristHash) : null;
317	        const selector = new MoveSelector(forcing, ttMove, this.killerMoves, ply);
318	
319	        let bestScore = standPat;
320	        let legalForcingFound = false;
321	        let move: InternalMove | null;
322	
323	        while ((move = selector.pickNext()) !== null) {
324	            if ((move.flags & MoveFlag.PROMOTION) && move.promotionPiece) {
325	                const isQueenPromotion =
326	                    move.promotionPiece === Piece.WHITE_QUEEN ||
327	                    move.promotionPiece === Piece.BLACK_QUEEN;
328	                if (!isQueenPromotion) continue;
329	            }
330	
331	            const child = copyBoard(board);
332	            applyMoveComplete(child, move);
333	
334	            // Skip illegal moves
335	            if (this.isIllegalMove(child)) continue;
336	
337	            legalForcingFound = true;
338	            const score = -this.quiescence(child, -beta, -alpha, ply + 1, qDepth + 1);
339	
340	            if (score > bestScore) bestScore = score;
341	            if (score >= beta) return score;
342	            if (score > alpha) alpha = score;
343	        }
344	
345	        // Mate detection: if in check and no legal forcing move, check for any legal escape
346	        if (!legalForcingFound && isKingInCheck(board)) {
347	            for (const m of allMoves) {
348	                // Skip forcing moves (already checked above)
349	                if ((m.flags & MoveFlag.CAPTURE) || (m.flags & MoveFlag.PROMOTION)) continue;
350	                const child = copyBoard(board);
351	                applyMoveComplete(child, m);
352	                if (!this.isIllegalMove(child)) return standPat; // Has legal quiet escape
353	            }
354	            return SCORE_MIN + ply; // Checkmate
355	        }
356	
357	        return bestScore;
358	    }
359	
360	    /**
361	     * Check if a move was illegal (left own king in check) after applyMoveComplete.
362	     * After applyMoveComplete, board.turn has switched, so the "previous" side
363	     * is the opponent of board.turn.
364	     */
365	    private isIllegalMove(child: InternalBoard): boolean {
366	        const prevColor = child.turn === InternalColor.WHITE ? InternalColor.BLACK : InternalColor.WHITE;
367	        const prevKingBB = prevColor === InternalColor.WHITE ? child.whiteKing : child.blackKing;
368	        if (prevKingBB === 0n) return false;
369	        const prevKingSq = getLowestSetBit(prevKingBB);
370	        return isSquareAttacked(child, prevKingSq, child.turn);
371	    }
372	
373	    // NOTE: Board cloning must preserve bitboards/mailbox/game flags.
374	    // Use the engine's canonical copier to avoid subtle corruption.
375	}
