    setPiece(board, squareToIndex('E5'), Piece.WHITE_PAWN);
    setPiece(board, squareToIndex('D6'), Piece.BLACK_PAWN); // pawn on d6, only one step from d7
    board.enPassantSquare = null; // since it only moved one square, no EP square set
    board.turn = InternalColor.WHITE;
