1	/**
2	 * Conversion utilities between square notation and internal indices
3	 */
4	
5	import { Square, SquareIndex, FileIndex, RankIndex, Column, Row } from '../types';
6	import { COLUMNS, ROWS } from './constants';
7	
8	// ==================== Square ↔ Index Conversion ====================
9	
10	/**
11	 * Convert square notation (e.g., "A1", "E4") to square index (0-63)
12	 *
13	 * Board layout:
14	 * 56 57 58 59 60 61 62 63  (Rank 8) - A8 to H8
15	 * 48 49 50 51 52 53 54 55  (Rank 7)
16	 * ...
17	 *  8  9 10 11 12 13 14 15  (Rank 2)
18	 *  0  1  2  3  4  5  6  7  (Rank 1) - A1 to H1
19	 *
20	 * @param square - Square notation (case-insensitive)
21	 * @returns Square index (0-63)
22	 * @throws Error if square notation is invalid
23	 */
24	export function squareToIndex(square: Square): SquareIndex {
25	    const normalized = square.toUpperCase();
26	
27	    if (normalized.length !== 2) {
28	        throw new Error(`Invalid square notation: ${square}`);
29	    }
30	
31	    const file = normalized[0] as Column;
32	    const rank = normalized[1] as Row;
33	
34	    const fileIndex = COLUMNS.indexOf(file);
35	    const rankIndex = ROWS.indexOf(rank);
36	
37	    if (fileIndex === -1 || rankIndex === -1) {
38	        throw new Error(`Invalid square notation: ${square}`);
39	    }
40	
41	    return (rankIndex * 8 + fileIndex) as SquareIndex;
42	}
43	
44	/**
45	 * Convert square index (0-63) to square notation (e.g., "A1", "E4")
46	 *
47	 * @param index - Square index (0-63)
48	 * @returns Square notation in uppercase
49	 * @throws Error if index is out of range
50	 */
51	export function indexToSquare(index: SquareIndex): Square {
52	    if (index < 0 || index > 63) {
53	        throw new Error(`Invalid square index: ${index}`);
54	    }
55	
56	    const fileIndex = index % 8;
57	    const rankIndex = Math.floor(index / 8);
58	
59	    return `${COLUMNS[fileIndex]}${ROWS[rankIndex]}`;
60	}
61	
62	// ==================== File/Rank Conversion ====================
63	
64	/**
65	 * Get file index (0-7) from square index
66	 *
67	 * @param index - Square index (0-63)
68	 * @returns File index (0=A, 1=B, ..., 7=H)
69	 */
70	export function getFileIndex(index: SquareIndex): FileIndex {
71	    return (index % 8) as FileIndex;
72	}
73	
74	/**
75	 * Get rank index (0-7) from square index
76	 *
77	 * @param index - Square index (0-63)
78	 * @returns Rank index (0=1, 1=2, ..., 7=8)
79	 */
80	export function getRankIndex(index: SquareIndex): RankIndex {
81	    return Math.floor(index / 8) as RankIndex;
82	}
83	
84	/**
85	 * Get file from square notation
86	 *
87	 * @param square - Square notation (case-insensitive)
88	 * @returns File index (0-7)
89	 */
90	export function getFile(square: Square): FileIndex {
91	    const normalized = square.toUpperCase();
92	    const fileIndex = COLUMNS.indexOf(normalized[0] as Column);
93	    if (fileIndex === -1) {
94	        throw new Error(`Invalid square notation: ${square}`);
95	    }
96	    return fileIndex as FileIndex;
97	}
98	
99	/**
100	 * Get rank from square notation
101	 *
102	 * @param square - Square notation (case-insensitive)
103	 * @returns Rank index (0-7)
104	 */
105	export function getRank(square: Square): RankIndex {
106	    const normalized = square.toUpperCase();
107	    const rankIndex = ROWS.indexOf(normalized[1] as Row);
108	    if (rankIndex === -1) {
109	        throw new Error(`Invalid square notation: ${square}`);
110	    }
111	    return rankIndex as RankIndex;
112	}
113	
114	/**
115	 * Create square index from file and rank indices
116	 *
117	 * @param file - File index (0-7)
118	 * @param rank - Rank index (0-7)
119	 * @returns Square index (0-63)
120	 */
121	export function fileRankToIndex(file: FileIndex, rank: RankIndex): SquareIndex {
122	    return (rank * 8 + file) as SquareIndex;
123	}
124	
125	// ==================== Validation ====================
126	
127	/**
128	 * Check if square notation is valid
129	 *
130	 * @param square - Square notation
131	 * @returns true if valid
132	 */
133	export function isValidSquare(square: string): boolean {
134	    if (typeof square !== 'string' || square.length !== 2) {
135	        return false;
136	    }
137	
138	    const normalized = square.toUpperCase();
139	    const file = normalized[0];
140	    const rank = normalized[1];
141	
142	    return COLUMNS.includes(file as Column) && ROWS.includes(rank as Row);
143	}
144	
145	/**
146	 * Check if square index is valid
147	 *
148	 * @param index - Square index
149	 * @returns true if valid (0-63)
150	 */
151	export function isValidIndex(index: number): boolean {
152	    return Number.isInteger(index) && index >= 0 && index <= 63;
153	}
154	
155	// ==================== Bitboard Helpers ====================
156	
157	/**
158	 * Convert square index to bitboard (single bit set)
159	 *
160	 * @param index - Square index (0-63)
161	 * @returns Bitboard with single bit set
162	 */
163	export function indexToBitboard(index: SquareIndex): bigint {
164	    return 1n << BigInt(index);
165	}
166	
167	/**
168	 * Convert square notation to bitboard
169	 *
170	 * @param square - Square notation
171	 * @returns Bitboard with single bit set
172	 */
173	export function squareToBitboard(square: Square): bigint {
174	    return indexToBitboard(squareToIndex(square));
175	}
176	
177	/**
178	 * Get all set bits (square indices) from a bitboard
179	 *
180	 * @param bitboard - Bitboard to extract indices from
181	 * @returns Array of square indices where bits are set
182	 */
183	export function bitboardToIndices(bitboard: bigint): SquareIndex[] {
184	    const indices: SquareIndex[] = [];
185	    let bb = bitboard;
186	
187	    while (bb !== 0n) {
188	        const index = getLowestSetBit(bb);
189	        indices.push(index);
190	        bb &= bb - 1n; // Clear lowest set bit
191	    }
192	
193	    return indices;
194	}
195	
196	// De Bruijn constant and lookup table for O(1) bit scanning
197	const DE_BRUIJN_64 = 0x03F79D71B4CB0A89n;
198	const MASK_64 = 0xFFFFFFFFFFFFFFFFn;
199	const DE_BRUIJN_TABLE = new Int8Array(64);
200	for (let i = 0; i < 64; i++) {
201	    DE_BRUIJN_TABLE[Number((((1n << BigInt(i)) * DE_BRUIJN_64) & MASK_64) >> 58n)] = i;
202	}
203	
204	/**
205	 * Get the index of the lowest set bit in a bitboard (O(1) via De Bruijn)
206	 */
207	export function getLowestSetBit(bitboard: bigint): SquareIndex {
208	    if (bitboard === 0n) return -1 as SquareIndex;
209	    const isolated = bitboard & (-bitboard);
210	    return DE_BRUIJN_TABLE[Number(((isolated * DE_BRUIJN_64) & MASK_64) >> 58n)] as SquareIndex;
211	}
212	
213	/**
214	 * Get the index of the highest set bit in a bitboard
215	 */
216	export function getHighestSetBit(bitboard: bigint): SquareIndex {
217	    if (bitboard === 0n) return -1 as SquareIndex;
218	    let bb = bitboard;
219	    bb |= bb >> 1n;
220	    bb |= bb >> 2n;
221	    bb |= bb >> 4n;
222	    bb |= bb >> 8n;
223	    bb |= bb >> 16n;
224	    bb |= bb >> 32n;
225	    const msb = bb - (bb >> 1n);
226	    return DE_BRUIJN_TABLE[Number(((msb * DE_BRUIJN_64) & MASK_64) >> 58n)] as SquareIndex;
227	}
228	
229	/**
230	 * Count the number of set bits in a bitboard (population count)
231	 *
232	 * @param bitboard - Bitboard
233	 * @returns Number of set bits
234	 */
235	export function popCount(bitboard: bigint): number {
236	    let count = 0;
237	    let bb = bitboard;
238	
239	    while (bb !== 0n) {
240	        bb &= bb - 1n; // Clear lowest set bit
241	        count++;
242	    }
243	
244	    return count;
245	}
246	
247	// ==================== Distance Calculations ====================
248	
249	/**
250	 * Calculate Manhattan distance between two squares
251	 *
252	 * @param from - Source square index
253	 * @param to - Target square index
254	 * @returns Manhattan distance
255	 */
256	export function manhattanDistance(from: SquareIndex, to: SquareIndex): number {
257	    const fromFile = getFileIndex(from);
258	    const fromRank = getRankIndex(from);
259	    const toFile = getFileIndex(to);
260	    const toRank = getRankIndex(to);
261	
262	    return Math.abs(fromFile - toFile) + Math.abs(fromRank - toRank);
263	}
264	
265	/**
266	 * Calculate Chebyshev distance between two squares (king moves)
267	 *
268	 * @param from - Source square index
269	 * @param to - Target square index
270	 * @returns Chebyshev distance
271	 */
272	export function chebyshevDistance(from: SquareIndex, to: SquareIndex): number {
273	    const fromFile = getFileIndex(from);
274	    const fromRank = getRankIndex(from);
275	    const toFile = getFileIndex(to);
276	    const toRank = getRankIndex(to);
277	
278	    return Math.max(Math.abs(fromFile - toFile), Math.abs(fromRank - toRank));
279	}
280	
281	// ==================== Board Boundaries ====================
